</div>
<div style="font-size:10.5px;color:#666;line-height:1.35;margin-top:2px">
  Drag in the figure to orbit: the coil axis is vertical, perpendicular to the horizontal S–N pole axis, with the tube in the gap.
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── ELEMENT SPEC ─────────────────────────────────────────────────────────
 glass tube        → CylinderGeometry(0.14,0.14,5.6) + SphereGeometry cap + top flange, MeshPhysicalMaterial pale blue transparent
 sample column     → CylinderGeometry(0.10,0.10,3.6) + sphere cap, MeshStandardMaterial #E8951E, emissive driven by resonance
 resonance halo    → Sprite, additive radial-gradient CanvasTexture
 coil              → TubeGeometry over 22-turn helix, r=0.055, wound at R=0.26, #3FAE49
 blue collars (2)  → CylinderGeometry(0.34,0.34,0.35) #1B7FC4 + ribbing rings #5AB6E8
 magnet poles (2)  → CylinderGeometry(0.95,0.95,1.7) rotated π/2 about Z, metal #B9BCC0
 S / N letters     → PlaneGeometry CanvasTexture proud of each pole's front curved face
 rf generator      → BoxGeometry 3.0×1.1×2.0 beige + tilted top panel + LCD plane '9.56' + 2 knob cylinders + 6 button cylinders + 4 switch boxes
 detector box      → BoxGeometry 1.6×2.1×1.6 charcoal + side panel + 2 dials + silver knob + green/red pushbutton cylinders
 monitor           → bezel Box 3.1×2.1×0.18 + screen Plane 2.7×1.6 CanvasTexture spectrum + neck cylinder + elliptical base
 green cables (2)  → CatmullRomCurve3 → TubeGeometry r=0.035 #2F9E4F  generator → lower collar
 blue cables (2+2) → CatmullRomCurve3 → TubeGeometry r=0.035 #37A6DC  coil → detector, detector → monitor
 leader line       → Line, black, label anchor → glass above upper collar
 labels            → addLabel HTML overlays
─────────────────────────────────────────────────────────────────────────── */

/* ── lights (three-point rig) ─────────────────────────────────────────── */
scene.add(new THREE.AmbientLight(0xffffff, 0.55));
const keyL = new THREE.DirectionalLight(0xffffff, 0.85); keyL.position.set(-4, 6, 7); scene.add(keyL);
const fillL = new THREE.DirectionalLight(0xffffff, 0.45); fillL.position.set(7, 2, 3); scene.add(fillL);
const backL = new THREE.DirectionalLight(0xffffff, 0.25); backL.position.set(0, 3, -8); scene.add(backL);

/* ── part registry for highlight / dim ────────────────────────────────── */
const parts = [];
function addPart(obj, comps) {
  obj.traverse(o => {
    if (o.isMesh || o.isLine || o.isSprite) {
      const m = o.material;
      if (!m.userData.__base) {
        m.userData.__base = { o: m.opacity, t: m.transparent, e: m.emissive ? m.emissive.getHex() : null };
      }
      parts.push({ o, m, comps });
    }
  });
  return obj;
}
function std(color, opts = {}) {
  return new THREE.MeshStandardMaterial(Object.assign({ color, roughness: 0.55, metalness: 0.05 }, opts));
}

/* ── texture helpers ──────────────────────────────────────────────────── */
function textTexture(text, { w = 256, h = 256, font = 'bold 170px serif', color = '#111', bg = null } = {}) {
  const cv = document.createElement('canvas'); cv.width = w; cv.height = h;
  const c = cv.getContext('2d');
  if (bg) { c.fillStyle = bg; c.fillRect(0, 0, w, h); }
  c.fillStyle = color; c.font = font; c.textAlign = 'center'; c.textBaseline = 'middle';
  c.fillText(text, w / 2, h / 2 + 4);
  const t = new THREE.CanvasTexture(cv); t.colorSpace = THREE.SRGBColorSpace; return t;
}
function haloTexture() {
  const cv = document.createElement('canvas'); cv.width = cv.height = 128;
  const c = cv.getContext('2d');
  const g = c.createRadialGradient(64, 64, 0, 64, 64, 64);
  g.addColorStop(0, 'rgba(255,255,220,1)');
  g.addColorStop(0.35, 'rgba(255,225,120,0.55)');
  g.addColorStop(1, 'rgba(255,200,60,0)');
  c.fillStyle = g; c.fillRect(0, 0, 128, 128);
  const t = new THREE.CanvasTexture(cv); t.colorSpace = THREE.SRGBColorSpace; return t;
}

/* ── 1. glass tube ────────────────────────────────────────────────────── */
const tubeGroup = new THREE.Group(); scene.add(tubeGroup);
const glassMat = new THREE.MeshPhysicalMaterial({
  color: 0xdaeef7, roughness: 0.08, metalness: 0.0, transparent: true,
  opacity: 0.3, depthWrite: false, side: THREE.DoubleSide, clearcoat: 1
});
const tubeBody = new THREE.Mesh(new THREE.CylinderGeometry(0.14, 0.14, 5.5, 32, 1, true), glassMat);
tubeBody.position.y = 0.45; tubeGroup.add(tubeBody);
const tubeBottom = new THREE.Mesh(new THREE.SphereGeometry(0.14, 24, 12, 0, Math.PI * 2, Math.PI / 2, Math.PI / 2), glassMat);
tubeBottom.position.y = -2.3; tubeGroup.add(tubeBottom);
const tubeFlange = new THREE.Mesh(new THREE.CylinderGeometry(0.175, 0.145, 0.2, 32, 1, true), glassMat);
tubeFlange.position.y = 3.1; tubeGroup.add(tubeFlange);

/* ── 2. orange sample column + halo ───────────────────────────────────── */
const sampleMat = std(0xE8951E, { roughness: 0.35, emissive: 0x000000 });
sampleMat.userData.skipEmissive = true;
const sample = new THREE.Mesh(new THREE.CylinderGeometry(0.10, 0.10, 3.6, 28), sampleMat);
sample.position.y = -0.2; tubeGroup.add(sample);
const sampleCap = new THREE.Mesh(new THREE.SphereGeometry(0.10, 20, 10, 0, Math.PI * 2, Math.PI / 2, Math.PI / 2), sampleMat);
sampleCap.position.y = -2.0; tubeGroup.add(sampleCap);

const haloMat = new THREE.SpriteMaterial({ map: haloTexture(), transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false });
const halo = new THREE.Sprite(haloMat);
halo.scale.set(1.6, 3.4, 1); halo.position.set(0, 0.0, 0); tubeGroup.add(halo);

/* ── 3. green helical coil ────────────────────────────────────────────── */
const coilPts = [];
const TURNS = 22, NSEG = TURNS * 26;
for (let i = 0; i <= NSEG; i++) {
  const t = i / NSEG, a = t * TURNS * Math.PI * 2;
  coilPts.push(new THREE.Vector3(0.26 * Math.cos(a), -0.9 + 1.9 * t, 0.26 * Math.sin(a)));
}
const coilCurve = new THREE.CatmullRomCurve3(coilPts);
const coil = new THREE.Mesh(new THREE.TubeGeometry(coilCurve, NSEG, 0.055, 8, false),
  std(0x3FAE49, { roughness: 0.4, metalness: 0.15 }));
tubeGroup.add(coil);

/* ── 4. blue collars ──────────────────────────────────────────────────── */
function collar(y) {
  const g = new THREE.Group();
