  const g = resonance * pulse;
  sampleMat.emissive.setRGB(1.0 * g, 0.92 * g, 0.55 * g);
  sampleMat.color.setRGB(0.91 + 0.09 * g, 0.58 + 0.40 * g, 0.12 + 0.75 * g);
  haloMat.opacity = 0.85 * g;
  halo.scale.set(1.4 + 0.5 * g, 3.2 + 0.4 * g, 1);
})();

/* ── demo steps ───────────────────────────────────────────────────────── */
const STEPS = [
  { title: 'Below resonance', field: 1.85, text: 'The rf generator holds 9.56 MHz steady while the field sits below the value any nucleus needs. Nothing in the sample absorbs and the spectrum baseline stays flat.' },
  { title: 'First nucleus in resonance', field: 2.03, text: 'Raising the field brings the most shielded protons into resonance: the sample column flashes and the corresponding upfield peak appears on the monitor.' },
  { title: 'A second, distinct nucleus', field: 2.31, text: 'A little more field and a chemically different set of nuclei absorbs. Because each environment resonates at its own field, the peaks land at separate positions rather than merging.' },
  { title: 'Full sweep recorded', field: 2.60, text: 'Sweeping to the top of the range has carried every nucleus through resonance, and the accumulated peaks of unequal height form the complete NMR spectrum on the display.' }
];
let stepIdx = 0, tween = null;
const stepTitle = document.getElementById('stepTitle'), stepText = document.getElementById('stepText');

function goToStep(i, cb) {
  stepIdx = Math.max(0, Math.min(STEPS.length - 1, i));
  const s = STEPS[stepIdx];
  stepTitle.textContent = (stepIdx + 1) + '. ' + s.title;
  stepText.textContent = s.text;
  const from = B0, to = s.field, t0 = performance.now(), dur = 1100;
  if (tween) cancelAnimationFrame(tween);
  (function step() {
    const k = Math.min(1, (performance.now() - t0) / dur);
    const e = k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2;
    updateField(from + (to - from) * e);
    if (k < 1) tween = requestAnimationFrame(step); else { tween = null; if (cb) cb(); }
  })();
}
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('btnPlay').addEventListener('click', () => {
  let i = 0;
  const run = () => { goToStep(i, () => { i++; if (i < STEPS.length) setTimeout(run, 900); }); };
  i = 0; run();
});
stepTitle.textContent = '1. ' + STEPS[0].title;
stepText.textContent = STEPS[0].text;
