/* ── part registry for highlight / dim ────────────────────────────────── */
const parts = [];
function addPart(obj, comps) {
  obj.traverse(o => {
    if (o.isMesh || o.isLine || o.isSprite) {
      const m = o.material;
      if (!m.userData.__base) {
        m.userData.__base = { o: m.opacity, t: m.transparent, e: m.emissive ? m.emissive.getHex() : null };
      }
      parts.push({ o, m, comps });
    }
  });
  return obj;
}
function std(color, opts = {}) {
  return new THREE.MeshStandardMaterial(Object.assign({ color, roughness: 0.6, metalness: 0.04 }, opts));
}

/* ── texture helpers ──────────────────────────────────────────────────── */
function letterTexture(text) {
  const w = 256, h = 256;
  const cv = document.createElement('canvas'); cv.width = w; cv.height = h;
  const c = cv.getContext('2d');
  c.clearRect(0, 0, w, h);
  c.fillStyle = '#000000';
  c.font = 'bold 215px Georgia, "Times New Roman", serif';
  c.textAlign = 'center'; c.textBaseline = 'middle';
  c.fillText(text, w / 2, h / 2 + 8);
  const t = new THREE.CanvasTexture(cv); t.colorSpace = THREE.SRGBColorSpace; return t;
}
function poleTexture() {
  const cv = document.createElement('canvas'); cv.width = 512; cv.height = 8;
  const c = cv.getContext('2d');
  const g = c.createLinearGradient(0, 0, 512, 0);
  g.addColorStop(0.00, '#bcc1c6');
  g.addColorStop(0.05, '#eef1f3');
  g.addColorStop(0.11, '#ffffff');
  g.addColorStop(0.20, '#e2e6e9');
  g.addColorStop(0.38, '#bec3c8');
  g.addColorStop(0.58, '#9ca2a7');
  g.addColorStop(0.80, '#b4b9be');
  g.addColorStop(1.00, '#bcc1c6');
  c.fillStyle = g; c.fillRect(0, 0, 512, 8);
  const t = new THREE.CanvasTexture(cv);
  t.colorSpace = THREE.SRGBColorSpace;
  t.wrapS = THREE.RepeatWrapping;
  return t;
}
function haloTexture() {
  const cv = document.createElement('canvas'); cv.width = cv.height = 128;
  const c = cv.getContext('2d');
  const g = c.createRadialGradient(64, 64, 0, 64, 64, 64);
  g.addColorStop(0, 'rgba(255,255,225,1)');
  g.addColorStop(0.35, 'rgba(255,225,120,0.55)');
  g.addColorStop(1, 'rgba(255,200,60,0)');
  c.fillStyle = g; c.fillRect(0, 0, 128, 128);
  const t = new THREE.CanvasTexture(cv); t.colorSpace = THREE.SRGBColorSpace; return t;
}

