const PEAKS = [
  { x: 0.18, h: 0.95, B: 2.03 },
  { x: 0.27, h: 0.45, B: 2.11 },
  { x: 0.31, h: 0.30, B: 2.15 },
  { x: 0.74, h: 1.00, B: 2.44 },
  { x: 0.81, h: 0.55, B: 2.52 }
];
function drawSpectrum(B0) {
  const W = specCv.width, H = specCv.height, c = specCtx;
  c.globalAlpha = 1;
  c.fillStyle = '#A8DCF0'; c.fillRect(0, 0, W, H);
  const baseY = H - H * 0.25;
  const avail = baseY - H * 0.07;
  PEAKS.forEach(p => {
    const appear = Math.max(0, Math.min(1, (B0 - p.B + 0.02) / 0.04));
    if (appear <= 0.001) return;
    const res = Math.abs(B0 - p.B) < 0.02;
    const x = W * (0.05 + p.x * 0.90);
    const h = avail * p.h * appear;
    c.globalAlpha = 0.45 + 0.55 * appear;
    c.strokeStyle = res ? '#FF2A10' : '#101010';
    c.lineWidth = res ? 9 : 5;
    if (res) { c.shadowColor = '#ff6a40'; c.shadowBlur = 14; }
    c.beginPath(); c.moveTo(x, baseY); c.lineTo(x, baseY - h); c.stroke();
    c.shadowBlur = 0;
    c.globalAlpha = 1;
  });
  c.strokeStyle = '#E0241E'; c.lineWidth = 4;
  c.beginPath(); c.moveTo(W * 0.02, baseY); c.lineTo(W * 0.98, baseY); c.stroke();
  specTex.needsUpdate = true;
}
