let currentHL = null;
function setHighlight(id) {
  currentHL = id;
  parts.forEach(p => {
    const b = p.m.userData.__base;
    const on = !id || p.comps.includes(id);
    p.m.opacity = on ? b.o : b.o * 0.20;
    p.m.transparent = on ? b.t : true;
    if (p.m.emissive && !p.m.userData.skipEmissive) {
      p.m.emissive.setHex(on && id ? 0x2c2c14 : (b.e || 0x000000));
    }
  });
  ['generator', 'coil', 'detector', 'monitor', 'none'].forEach(k => {
    const btn = document.getElementById('hl' + k);
    if (btn) btn.classList.toggle('active', (k === 'none' && !id) || k === id);
  });
}
